const ICONS={map:'M3 6l6-3 6 3 6-3v15l-6 3-6-3-6 3V6z M9 3v15 M15 6v15',network:'M9 3h6v5H9z M2 16h6v5H2z M16 16h6v5h-6z M12 8v4 M5 16v-4h14v4 M12 12v4 M9 16h6v5H9z',chart:'M4 3v18h17 M8 16v-5 M13 16V6 M18 16V9',route:'M5 5h9a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h10 M5 2v6 M16 18l3 3-3 3',layers:'M12 3L2 8l10 5 10-5-10-5z M2 12l10 5 10-5 M2 16l10 5 10-5',check:'M8 12l3 3 5-6 M21 12a9 9 0 1 1-4-7',flag:'M5 21V4 M5 4c5-5 9 5 15 0v10c-6 5-10-5-15 0',book:'M3 4c3-1 6-1 9 1 3-2 6-2 9-1v16c-3-1-6-1-9 1-3-2-6-2-9-1V4z M12 5v16',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h.1 M3 12h.1 M3 19h.1',maximize:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17h.1 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',play:'M8 4l12 8-12 8V4z',landmark:'M3 9h18L12 3 3 9z M5 12v6 M10 12v6 M15 12v6 M20 12v6 M2 21h20',coins:'M20 6c0 2-4 3-8 3S4 8 4 6s4-3 8-3 8 1 8 3z M4 6v5c0 2 4 3 8 3s8-1 8-3V6 M4 11v5c0 2 4 3 8 3s8-1 8-3v-5 M4 16v3c0 2 4 3 8 3s8-1 8-3v-3',users:'M16 21v-3a4 4 0 0 0-4-4H7a4 4 0 0 0-4 4v3 M15 4a4 4 0 0 1 0 8 M21 21v-3a4 4 0 0 0-3-4 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M2 12h20 M12 2a18 18 0 0 1 0 20 18 18 0 0 1 0-20',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 M7 9l5-5 5 5 M4 16v5h16v-5',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',chevron:'M6 9l6 6 6-6',bulb:'M9 18h6 M10 22h4 M8 15a7 7 0 1 1 8 0c-1 1-1 2-1 3H9c0-1 0-2-1-3',arrow:'M4 12h16 M15 7l5 5-5 5'};
function icon(name){return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+(ICONS[name]||ICONS.book)+'"/></svg>';}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});}
const statusLabels={unstarted:'未开始',learning:'学习中',mastered:'已掌握',weak:'需巩固'};
const statusColors={unstarted:'#bec9b2',learning:'#6e97b9',mastered:'#73a17c',weak:'#d2a15e'};
const STORE_KEY='public-admin-atlas-progress-v1';
const nodeById=Object.fromEntries(NODES.map(n=>[n.id,n]));
const moduleById=Object.fromEntries(MODULES.map(m=>[m.id,m]));
let records={},storageAvailable=true;
try{const saved=JSON.parse(storedRaw||'{}');records=validateRecords(saved.records||{});}catch(e){storageReadError=true;storageAvailable=false;}
function validateRecords(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('数据格式不正确');const clean={};for(const [id,r] of Object.entries(input)){if(!Object.hasOwn(nodeById,id))continue;if(!r||typeof r!=='object'||!(Object.hasOwn(statusLabels,r.status))||typeof (r.note??'')!=='string')throw Error('节点记录格式不正确');clean[id]={status:r.status,note:(r.note||'').slice(0,5000),updatedAt:typeof r.updatedAt==='string'?r.updatedAt:''};}return clean;}
let activeModule='all',search='',edgeMode='all',weakOnly=false,selected='public-interest',page='map',view='graph',zoom=1,toastTimer;
let questionOpen=false;
const statusOf=id=>records[id]?.status||'unstarted';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){if(storageReadError){storageAvailable=false;toast('原记录读取异常，已暂停保存；请先导出原始记录');updateSaveState();return;}try{localStorage.setItem(STORE_KEY,JSON.stringify({version:2,records,microRecords}));storageAvailable=true;}catch(e){storageAvailable=false;toast('浏览器无法保存，请及时导出学习记录');}updateSaveState();}
function updateSaveState(){document.querySelector('.save-state').innerHTML='<span></span>'+(storageReadError?'原记录读取异常，已暂停保存':storageAvailable?'进度保存在此浏览器':'记录尚未持久保存');let warning=$('storageWarning');if(!warning){warning=document.createElement('div');warning.id='storageWarning';warning.className='storage-warning';warning.setAttribute('role','alert');warning.innerHTML='<span></span><button type="button">打开数据管理</button>';document.querySelector('.topbar').after(warning);warning.querySelector('button').addEventListener('click',()=>{if(!$('helpDialog').open)$('helpDialog').showModal();});}warning.hidden=storageAvailable&&!storageReadError;warning.querySelector('span').textContent=storageReadError?'原记录读取异常，已暂停保存。请先打开数据管理，导出原始记录；刷新后本次修改会丢失。':'浏览器无法保存，本次修改可能丢失。请打开数据管理导出学习记录。';}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2700);}
function moduleCounts(id){const nodes=NODES.filter(n=>!id||n.m===id);const out={total:nodes.length,unstarted:0,learning:0,mastered:0,weak:0};nodes.forEach(n=>out[statusOf(n.id)]++);return out;}
function updateStats(){const c=moduleCounts();$('masteredStat').innerHTML=c.mastered+'<span> / 36 节点</span>';$('weakStat').innerHTML=c.weak+'<span> 个节点</span>';$('learningStat').innerHTML=c.learning+'<span> 个节点</span>';const pct=Math.round(c.mastered/c.total*100);$('masteryRing').style.setProperty('--pct',pct+'%');$('masteryRing').innerHTML='<span>'+pct+'%</span>';$('coverageStat').textContent=c.unstarted===36?'尚未开始':'已探索 '+(36-c.unstarted)+' / 36';$('continueBtn').innerHTML=icon('play')+(36-c.unstarted?'继续学习':'开始探索')+'<span>↗</span>';renderModuleCards();}
function renderNavigation(){
$('sideModules').innerHTML=MODULES.map(m=>'<button class="side-module '+(activeModule===m.id&&page==='map'?'active':'')+'" data-module="'+m.id+'"><span class="module-dot" style="background:'+m.color+'"></span>'+m.name+'<span class="count">06</span></button>').join('');
$('moduleFilters').innerHTML='<button class="filter-chip '+(activeModule==='all'?'active':'')+'" data-module="all">全部板块</button>'+MODULES.map(m=>'<button class="filter-chip '+(activeModule===m.id?'active':'')+'" data-module="'+m.id+'"><span class="module-dot" style="background:'+m.color+'"></span>'+m.name+'</button>').join('');
}
function renderModuleCards(){$('moduleCards').innerHTML=MODULES.map(m=>{const c=moduleCounts(m.id);return '<button class="module-card" data-module="'+m.id+'"><div class="module-card-head"><span style="color:'+m.color+';background:'+m.light+'">'+icon(m.icon)+'</span><b>↗</b></div><h3>'+m.name+'</h3><p>6 个核心节点</p><div class="progress-track"><span style="width:'+(c.mastered/6*100)+'%;background:'+m.color+'"></span></div><div class="module-card-foot"><span>已掌握 '+c.mastered+' / 6</span><span>'+Math.round(c.mastered/6*100)+'%</span></div></button>';}).join('');}
function filteredNodes(){return NODES.filter(n=>(activeModule==='all'||n.m===activeModule)&&(!weakOnly||statusOf(n.id)==='weak')&&(!search||normalizeStudySearch([n.name,n.desc,...n.terms,moduleById[n.m].name,...(MICRO_BY_NODE[n.id]||[]).flatMap(p=>[p.title,p.body,p.example,...Object.values(DEEP_NOTES[p.id])])].join(' ')).includes(normalizeStudySearch(search))));}
const preEdges=NODES.flatMap(n=>n.pre.map(p=>({from:p,to:n.id,type:'pre'})));
const crossEdges=CROSS.map(([from,to])=>({from,to,type:'cross'}));
function renderGraph(){
const visible=filteredNodes(),ids=new Set(visible.map(n=>n.id));
$('mapCount').textContent=visible.length+' 个节点';$('mapTitle').childNodes[0].textContent=(activeModule==='all'?'全景知识图谱':moduleById[activeModule].name)+' ';
$('mapHint').textContent=window.innerWidth<=540?'图谱可左右滑动 · 点击节点查看详情':activeModule==='all'?'选择一个节点，沿着联系继续探索':'聚焦当前板块 · 在节点详情中跳转跨板块联系';
$('emptyState').hidden=visible.length>0;
$('emptyState').querySelector('strong').textContent=weakOnly&&!search?'当前范围没有需巩固的节点':'没有匹配的知识节点';
$('emptyState').querySelector('p').textContent=weakOnly&&!search?'在节点详情中标记“需巩固”，这里会为你聚焦。':'试试其他关键词，或清除筛选条件。';
const pos={};let backgrounds='';const focus=activeModule!=='all'||(visible.length>0&&visible.length<=8&&search);
if(focus){const count=visible.length;const cols=count===1?1:2;const rows=Math.ceil(count/cols);const width=268,height=52;visible.forEach((n,i)=>{pos[n.id]={x:cols===1?346:132+(i%2)*428,y:rows<=1?280:110+Math.floor(i/2)*Math.min(150,440/Math.max(1,rows-1)),w:width,h:height};});const m=moduleById[activeModule];if(m)backgrounds='<text x="480" y="48" text-anchor="middle" fill="'+m.color+'" font-size="18" font-weight="500">'+m.name+'</text><text x="480" y="71" text-anchor="middle" fill="#a3b295" font-size="9" letter-spacing="2">'+m.en+'</text>';
}else{MODULES.forEach((m,mi)=>{if(!visible.some(n=>n.m===m.id))return;const x=20+(mi%3)*314,y=25+Math.floor(mi/3)*292; backgroundValue(m,x,y);function backgroundValue(m,x,y){backgrounds+='<rect x="'+x+'" y="'+y+'" width="292" height="264" rx="14" fill="'+m.light+'" fill-opacity=".75" stroke="'+m.color+'" stroke-opacity=".15"/><circle cx="'+(x+20)+'" cy="'+(y+26)+'" r="3" fill="'+m.color+'"/><text x="'+(x+32)+'" y="'+(y+30)+'" font-size="16" font-weight="500" fill="'+m.color+'">'+m.name+'</text><text x="'+(x+20)+'" y="'+(y+50)+'" font-size="6.6" letter-spacing="1.1" fill="'+m.color+'" opacity=".55">'+m.en+'</text>';}
NODES.filter(n=>n.m===m.id).forEach((n,i)=>{if(ids.has(n.id))pos[n.id]={x:x+12+(i%2)*138,y:y+81+Math.floor(i/2)*57,w:130,h:34};});});}
let edges='';const allEdges=[...preEdges,...crossEdges].filter(e=>ids.has(e.from)&&ids.has(e.to)&&(edgeMode==='all'||edgeMode===e.type));
allEdges.forEach(e=>{const a=pos[e.from],b=pos[e.to];if(!a||!b)return;const ax=a.x+a.w/2,ay=a.y+a.h/2,bx=b.x+b.w/2,by=b.y+b.h/2;let x1=ax,y1=ay,x2=bx,y2=by;if(Math.abs(bx-ax)>Math.abs(by-ay)*1.1){x1=ax+(bx>ax?1:-1)*a.w/2;x2=bx+(bx>ax?-1:1)*b.w/2;}else{y1=ay+(by>ay?1:-1)*a.h/2;y2=by+(by>ay?-1:1)*b.h/2;}const isSelected=e.from===selected||e.to===selected;const opacity=isSelected?.68:.14;const color=e.type==='pre'?'#7f9984':'#b29c72';const d=Math.abs(bx-ax)>Math.abs(by-ay)?'M'+x1+','+y1+' C'+((x1+x2)/2)+','+y1+' '+((x1+x2)/2)+','+y2+' '+x2+','+y2:'M'+x1+','+y1+' C'+x1+','+((y1+y2)/2)+' '+x2+','+((y1+y2)/2)+' '+x2+','+y2;edges+='<path class="graph-edge" d="'+d+'" fill="none" stroke="'+color+'" stroke-width="'+(isSelected?1.7:1.1)+'" opacity="'+opacity+'" '+(e.type==='cross'?'stroke-dasharray="5 4"':'marker-end="url(#arrowhead)"')+'><title>'+escapeHTML(nodeById[e.from].name)+' '+(e.type==='pre'?'→ 建议先学于':'↔ 交叉联系')+' '+escapeHTML(nodeById[e.to].name)+'</title></path>';});
let nodes='';visible.forEach(n=>{const p=pos[n.id];if(!p)return;const m=moduleById[n.m],isSelected=selected===n.id,st=statusOf(n.id);nodes+='<g class="graph-node" role="button" tabindex="0" aria-label="'+n.name+'，'+statusLabels[st]+'" aria-pressed="'+isSelected+'" data-node="'+n.id+'"><title>'+n.name+' · '+statusLabels[st]+'</title>'+(isSelected?'<rect x="'+(p.x-4)+'" y="'+(p.y-4)+'" width="'+(p.w+8)+'" height="'+(p.h+8)+'" rx="'+(focus?13:(n.name.length>=9?11.1:12.2))+'" fill="'+m.color+'" fill-opacity=".1"/>':'')+'<rect class="node-shape" x="'+p.x+'" y="'+p.y+'" width="'+p.w+'" height="'+p.h+'" rx="'+(focus?9:6)+'" fill="'+(isSelected?m.color:'#fff')+'" stroke="'+(isSelected?m.color:'#dce4d6')+'" stroke-width="1"/><circle cx="'+(p.x+13)+'" cy="'+(p.y+p.h/2)+'" r="'+(focus?3.5:2.6)+'" fill="'+(isSelected&&st==='unstarted'?'#d4e5c6':statusColors[st])+'"/><text x="'+(p.x+(focus?27:23))+'" y="'+(p.y+p.h/2+.5)+'" dominant-baseline="middle" font-size="'+(focus?13:(n.name.length>=9?11.1:12.2))+'" fill="'+(isSelected?'#fff':'#74846b')+'">'+n.name+'</text>'+(focus?'<text x="'+(p.x+p.w-12)+'" y="'+(p.y+p.h/2)+'" text-anchor="end" dominant-baseline="middle" font-size="9" fill="'+(isSelected?'#d4e2cc':'#a4b294')+'">'+statusLabels[st]+'</text>':'')+'</g>';});
$('knowledgeGraph').innerHTML='<defs><marker id="arrowhead" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L8 4L0 8" fill="#7f9984"/></marker></defs><g id="graphScene">'+backgrounds+edges+nodes+'</g>';
applyZoom();$('nodeList').innerHTML=visible.length?visible.map(n=>'<button class="list-node" data-node="'+n.id+'"><span class="status-dot '+statusOf(n.id)+'"></span><span>'+n.name+'</span><small>'+moduleById[n.m].name+' · '+statusLabels[statusOf(n.id)]+'</small><b>↗</b></button>').join(''):'<div class="empty-copy"><h3>没有匹配的知识节点</h3><p>调整模块、关键词或巩固筛选后重试。</p></div>';
}
function applyZoom(){const scene=$('graphScene');if(scene)scene.setAttribute('transform','translate('+(480*(1-zoom))+','+(325*(1-zoom))+') scale('+zoom+')');$('zoomValue').textContent=Math.round(zoom*100)+'%';}
function relationLink(id){const n=nodeById[id];if(!n)return '';return '<button class="related-link" data-jump="'+id+'">'+n.name+'<em>↗</em></button>';}
function renderDetail(){const n=nodeById[selected],m=moduleById[n.m],st=statusOf(n.id);const index=NODES.indexOf(n)+1;const next=NODES.filter(x=>x.pre.includes(n.id));$('detailPanel').innerHTML='<div class="detail-head"><div class="detail-eyebrow"><span class="detail-module" style="color:'+m.color+'"><span class="module-dot" style="background:'+m.color+'"></span>'+m.name+'</span><span class="detail-index">NODE '+String(index).padStart(2,'0')+' / 36</span></div><h2>'+n.name+'</h2><span class="detail-state"><span class="status-dot '+st+'"></span>'+statusLabels[st]+'<span> · 核心概念</span></span></div><div class="detail-body"><p class="detail-description">'+n.desc+'</p><div class="term-tags">'+n.terms.map(t=>'<span>'+t+'</span>').join('')+'</div><div class="detail-section"><h3>'+icon('bulb')+'理解辨析</h3><div class="distinction">'+n.dist+'</div></div><div class="detail-section"><h3>'+icon('route')+'建议先学</h3>'+(n.pre.length?'<div class="related-links">'+n.pre.map(relationLink).join('')+'</div>':'<p class="detail-small">基础起点，可以从这里开始。</p>')+'</div><div class="detail-section"><h3>'+icon('link')+'交叉联系</h3><div class="related-links">'+n.related.map(relationLink).join('')+'</div></div>'+(next.length?'<div class="detail-section"><h3>'+icon('arrow')+'学完接着看</h3><div class="related-links">'+next.slice(0,3).map(x=>relationLink(x.id)).join('')+'</div></div>':'')+'<div class="detail-section"><button class="question-button '+(questionOpen?'open':'')+'" id="questionToggle" aria-expanded="'+questionOpen+'">用一个问题检查理解'+icon('chevron')+'</button><p class="question-text" id="questionText" '+(questionOpen?'':'hidden')+'>'+n.question+'</p></div>'+renderNodeExpansion(n)+'<div class="detail-section"><h3>我的理解笔记 <span class="detail-small">自动保存</span></h3><textarea class="note-input" id="nodeNote" aria-label="我的理解笔记" maxlength="5000" placeholder="用自己的话记下理解或疑问…">'+escapeHTML(records[n.id]?.note||'')+'</textarea></div></div><div class="detail-progress"><div>我的掌握程度<span>点击标记，自动保存</span></div><div class="status-options">'+Object.entries(statusLabels).map(([status,label])=>'<button class="status-btn '+(st===status?'active':'')+'" data-status="'+status+'" aria-pressed="'+(st===status)+'">'+label+'</button>').join('')+'</div></div>';
}
function selectNode(id,jump=false,scroll=true){
  if(!Object.hasOwn(nodeById,id))return;
  if(jump){
    activeModule=nodeById[id].m;search='';weakOnly=false;
    $('searchInput').value='';$('weakOnly').checked=false;
    setPage('map',false);
  }
  selected=id;questionOpen=false;
  renderNavigation();renderGraph();renderDetail();
  if(scroll&&window.innerWidth<=780){
    const behavior=matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth';
    $('detailPanel').scrollIntoView({behavior,block:'start'});
  }
}
function setStatus(status){const n=nodeById[selected];records[n.id]={status,note:records[n.id]?.note||'',updatedAt:new Date().toISOString()};save();updateStats();renderGraph();renderDetail();renderReview();renderPaths();renderMicroReview();if(storageAvailable)toast(n.name+' · '+statusLabels[status]);}
function setModule(id){activeModule=id;search='';weakOnly=false;zoom=1;$('searchInput').value='';$('weakOnly').checked=false;const n=NODES.find(n=>id==='all'||n.m===id);if(id!=='all'&&nodeById[selected].m!==id)selected=n.id;setPage('map',false);renderNavigation();renderGraph();renderDetail();window.scrollTo({top:0,behavior:'smooth'});}
const pageInfo={map:['知识地图','公共管理知识地图','从六大板块浏览概念，查看前置知识、关联主题和精读。'],library:['知识点库','公共管理知识点库','按概念、学者或关键词检索 '+MICRO_POINTS.length+' 篇精读、概念对照和来源。'],review:['复习看板','复习看板','查看已掌握、需巩固和收藏的知识，继续上次的学习。'],path:['学习路径','公共管理学习路径','按主题串读知识点，在案例和自测中检验理解。']};
function setPage(next,scroll=true){page=next;document.body.dataset.currentPage=next;for(const p of ['map','library','review','path'])$(p+'Page').hidden=p!==next;document.querySelectorAll('.nav-item').forEach(link=>{const active=link.dataset.page===next;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});$('breadcrumb').textContent=pageInfo[next][0];$('pageTitle').textContent=pageInfo[next][1];$('pageSubtitle').textContent=pageInfo[next][2];renderNavigation();if(next==='library')renderLibrary();if(next==='review'){renderReview();renderMicroReview();}if(next==='path')renderPaths();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function renderReview(){$('reviewModules').innerHTML=MODULES.map(m=>{const c=moduleCounts(m.id);return '<div class="review-module"><div class="review-module-top"><button data-module="'+m.id+'"><span class="module-dot" style="background:'+m.color+'"></span>'+m.name+' ↗</button><span>已掌握 '+c.mastered+' / 6 · '+Math.round(c.mastered/6*100)+'%</span></div><div class="stacked-progress">'+['mastered','learning','weak'].map(st=>'<span style="width:'+c[st]/6*100+'%;background:'+statusColors[st]+'"></span>').join('')+'</div><div class="review-meta">'+['mastered','learning','weak','unstarted'].map(st=>'<span><i class="status-dot '+st+'"></i>'+statusLabels[st]+' '+c[st]+'</span>').join('')+'</div></div>';}).join('');const weak=NODES.filter(n=>statusOf(n.id)==='weak');$('weakList').innerHTML=weak.length?weak.map(n=>'<button class="list-node" data-jump="'+n.id+'"><span class="status-dot weak"></span><span>'+n.name+'</span><small>'+moduleById[n.m].name+'</small><b>↗</b></button>').join(''):'<div class="empty-copy">'+icon('flag')+'<h3>还没有标记薄弱节点</h3><p>学习中发现不熟悉的内容，<br>标记为“需巩固”即可加入清单。</p></div>';const learning=NODES.filter(n=>statusOf(n.id)==='learning');$('learningList').innerHTML=learning.length?learning.map(n=>'<button class="learning-card" data-jump="'+n.id+'"><i class="status-dot learning"></i>'+n.name+'<span>↗</span></button>').join(''):'<p class="muted">从知识地图选择一个节点，并将它标为“学习中”。</p>';}
const PATHS=[{title:'理解公共性与政府',desc:'先问政府为何行动、应当追求什么，再认识行政组织。',ids:['public-interest','gov-function','value-fact','bureaucracy','accountability','paradigms']},{title:'掌握组织运行逻辑',desc:'从结构与决策出发，理解组织中的人、环境和制度。',ids:['org-structure','bounded-rationality','contingency','motivation','org-culture','institutions']},{title:'串起政策分析过程',desc:'把公共问题、工具选择、基层执行与结果评估连接起来。',ids:['policy-problem','policy-decision','policy-tools','implementation','evaluation','policy-change']},{title:'认识公共资源配置',desc:'理解公共产品、财政职能，再进入预算、央地与债务问题。',ids:['public-goods','externalities','finance-role','budget','fiscal-relations','debt']},{title:'理解公共部门用人',desc:'从岗位职责进入选育用留，兼顾绩效、伦理与公共责任。',ids:['hr-planning','recruitment','training','performance','compensation','ethics']},{title:'走向综合治理问题',desc:'在法治与公共价值的约束下，理解多元协作和数字转型。',ids:['rule-law','decentralization','collaboration','digital','participation','public-value']}];
function renderPaths(){$('learningPath').innerHTML=PATHS.map((p,i)=>'<article class="path-card"><span>0'+(i+1)+'</span><h2>'+p.title+'</h2><p>'+p.desc+'</p>'+p.ids.map(id=>'<button class="related-link" data-jump="'+id+'"><i class="status-dot '+statusOf(id)+'"></i> '+nodeById[id].name+'<span>'+statusLabels[statusOf(id)]+' ↗</span></button>').join('')+'</article>').join('');}
document.addEventListener('click',e=>{const module=e.target.closest('[data-module]');if(module){setModule(module.dataset.module);return;}const nav=e.target.closest('[data-page]');if(nav){if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();navigatePage(nav.dataset.page,{section:nav.dataset.pageSection});return;}const jump=e.target.closest('[data-jump]');if(jump){selectNode(jump.dataset.jump,true);return;}const node=e.target.closest('[data-node]');if(node){selectNode(node.dataset.node);return;}const status=e.target.closest('[data-status]');if(status){setStatus(status.dataset.status);return;}const edge=e.target.closest('[data-edge]');if(edge){edgeMode=edge.dataset.edge;document.querySelectorAll('[data-edge]').forEach(b=>b.classList.toggle('active',b.dataset.edge===edgeMode));renderGraph();return;}if(e.target.closest('#questionToggle')){questionOpen=!questionOpen;$('questionText').hidden=!questionOpen;$('questionToggle').classList.toggle('open',questionOpen);$('questionToggle').setAttribute('aria-expanded',String(questionOpen));}});
document.addEventListener('keydown',e=>{const t=e.target;if((e.key==='Enter'||e.key===' ')&&t.matches('.graph-node,.list-node[data-node]')){e.preventDefault();selectNode(t.dataset.node);$('topicReadingTitle')?.focus({preventScroll:true});}if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(t.tagName)&&!$('helpDialog').open&&!$('pointReader').open&&!$('quickFind').open){e.preventDefault();if(page==='library'){if(libraryTab==='compare'&&$('comparisonSearch')){$('comparisonSearch').focus();}else if(libraryTab==='reading'&&$('sourceSearch')){$('sourceSearch').focus();}else if(libraryTab==='textbooks'){$('textbookHeading').focus();}else{if(libraryTab!=='points'){libraryTab='points';renderLibrary();}$('microSearch').focus();}}else{setPage('map',false);$('searchInput').focus();}}});
$('searchInput').addEventListener('input',e=>{search=e.target.value.trim().toLowerCase();zoom=1;renderGraph();});
$('weakOnly').addEventListener('change',e=>{weakOnly=e.target.checked;renderGraph();});
document.addEventListener('input',e=>{if(e.target.id==='nodeNote'){records[selected]={status:statusOf(selected),note:e.target.value,updatedAt:new Date().toISOString()};save();}});
$('clearFilters').addEventListener('click',()=>{activeModule='all';search='';weakOnly=false;zoom=1;$('searchInput').value='';$('weakOnly').checked=false;renderNavigation();renderGraph();});
$('zoomIn').addEventListener('click',()=>{zoom=Math.min(1.8,Math.round((zoom+.2)*10)/10);applyZoom();});$('zoomOut').addEventListener('click',()=>{zoom=Math.max(.6,Math.round((zoom-.2)*10)/10);applyZoom();});$('zoomReset').addEventListener('click',()=>{zoom=1;applyZoom();});
function setView(next){view=next;$('graphWrap').hidden=view!=='graph';$('nodeList').hidden=view!=='list';$('graphView').classList.toggle('active',view==='graph');$('listView').classList.toggle('active',view==='list');$('graphView').setAttribute('aria-pressed',String(view==='graph'));$('listView').setAttribute('aria-pressed',String(view==='list'));}
$('graphView').addEventListener('click',()=>setView('graph'));$('listView').addEventListener('click',()=>setView('list'));
$('helpBtn').addEventListener('click',()=>$('helpDialog').showModal());$('closeHelp').addEventListener('click',()=>$('helpDialog').close());$('helpDialog').addEventListener('click',e=>{if(e.target===$('helpDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('continueBtn').addEventListener('click',()=>{const next=NODES.find(n=>statusOf(n.id)==='learning')||NODES.find(n=>statusOf(n.id)==='weak')||NODES.find(n=>statusOf(n.id)==='unstarted')||NODES[0];selectNode(next.id,true);if(window.innerWidth>780)$('detailPanel').scrollIntoView({behavior:'smooth',block:'center'});});
$('exportBtn').addEventListener('click',()=>{if(storageReadError&&storedRaw===null){toast('无法读取原始记录，未能导出');return;}const data=storageReadError?storedRaw:JSON.stringify({app:'public-admin-atlas',version:2,exportedAt:new Date().toISOString(),records,microRecords},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=(storageReadError?'public-admin-atlas-original-':'public-admin-atlas-progress-')+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(storageReadError?'已导出原始记录，可能需要修复':'学习记录已导出');});
$('importBtn').addEventListener('click',()=>$('importFile').click());$('importFile').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>1000000)throw Error('文件过大');const data=JSON.parse(await f.text());const imported=parseStudyBackup(data);const nodeConflicts=Object.keys(imported.records).filter(id=>Object.hasOwn(records,id)).length;const pointConflicts=Object.keys(imported.microRecords).filter(id=>Object.hasOwn(microRecords,id)).length;if((nodeConflicts||pointConflicts)&&!confirm('备份与当前记录有 '+nodeConflicts+' 个节点、'+pointConflicts+' 个知识点重叠。导入会用备份覆盖这些记录，包括笔记和学习状态；其他记录保留。建议先导出当前记录。是否继续？'))return;records={...records,...imported.records};microRecords={...microRecords,...imported.microRecords};save();updateStats();renderGraph();renderDetail();renderReview();renderPaths();renderLibrary();renderMicroReview();if(storageAvailable)toast('已导入 '+Object.keys(imported.records).length+' 个节点、'+Object.keys(imported.microRecords).length+' 个小知识点记录');}catch(err){toast('导入失败：'+err.message);}finally{e.target.value='';if(typeof restoreRecordImportFocus==='function')restoreRecordImportFocus();}});
hydrateIcons();renderNavigation();updateStats();renderGraph();renderDetail();renderReview();renderPaths();renderLibrary();renderMicroReview();updateSaveState();
